var e=localStorage.getItem(`account_id`);async function t(){let t=document.querySelector(`#client-name`);if(!(!t||!e))try{let n=await(await fetch(`http://localhost:3001/api/auth/clients/${e}`)).json();if(!n.success||!n.client)throw Error(n.message||`Unable to load client profile.`);t.textContent=[n.client.firstname,n.client.lastname].filter(Boolean).join(` `)||`Client`}catch(e){console.error(`CLIENT NAME ERROR:`,e)}}export{t};